import { ChangeDetectionStrategy, Component } from '@angular/core';
import { CommonModule } from '@angular/common';

interface MenuItem {
  tabs: string[];
  imageUrl: string;
  name: string;
  description: string;
  price: string;
  id: number;
}

@Component({
  selector: 'menu',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './menu.component.html',
  styleUrls: ['./menu.component.css'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MenuComponent {
  activeTab = 'ყველა';

  tabs: string[] = [
    'ყველა',
    'ბურგერი',
    'პიცა',
    'ხორცეული',
    'სალათი',
    'ზღვის პროდუქტები',
    'დესერტი',
    'სასმელი',
  ];

  menuItems: MenuItem[] = [
    {
      tabs: ['ყველა', 'პიცა'],
      imageUrl: 'https://images.unsplash.com/photo-1513104890138-7c749659a591?w=600',
      name: 'ორმაგი ყველის პიცა',
      description: 'ორმაგი ყველი, ორმაგი არომატი.',
      price: '15.30₾',
      id: 1,
    },
    {
      tabs: ['ყველა', 'ზღვის პროდუქტები'],
      imageUrl: 'https://images.unsplash.com/photo-1565680018434-b513d5e5fd47?w=600',
      name: 'კრევეტები',
      description: 'ახალი და გემრიელი ზღვის პროდუქტები.',
      price: '23.99₾',
      id: 2,
    },
    {
      tabs: ['ყველა', 'ბურგერი', 'ხორცეული'],
      imageUrl: 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=600',
      name: 'ორმაგი მაკ ბურგერი',
      description: 'ორმაგი სიამოვნება ყველა ლუკმაში.',
      price: '13.80₾',
      id: 3,
    },
    {
      tabs: ['ყველა', 'სალათი'],
      imageUrl: 'https://images.unsplash.com/photo-1550304943-4f24f54ddde9?w=600',
      name: 'სალათი ცეზარი',
      description: 'გემოს ზეიმი.',
      price: '18₾',
      id: 4,
    },
    {
      tabs: ['ყველა', 'დესერტი'],
      imageUrl: 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=600',
      name: 'ხილის ტორტი',
      description: 'ახალი ხილი და ნაზი კრემი.',
      price: '23.99₾',
      id: 5,
    },
    {
      tabs: ['ყველა', 'პიცა'],
      imageUrl: 'https://images.unsplash.com/photo-1571407970349-bc81e7e96d47?w=600',
      name: 'დიდი იტალიური პიცა',
      description: 'იტალიური არომატი ყველა ნაჭერში.',
      price: '23.99₾',
      id: 6,
    },
    {
      tabs: ['ყველა', 'სასმელი'],
      imageUrl: 'https://images.unsplash.com/photo-1621263764928-df1444c5e859?w=600',
      name: 'ლიმონათი',
      description: 'ციტრუსის არომატი ყველა ყლუპში.',
      price: '7₾',
      id: 7,
    },
    {
      tabs: ['ყველა', 'ბურგერი', 'ხორცეული'],
      imageUrl: 'https://images.unsplash.com/photo-1606755962773-d324e0a13086?w=600',
      name: 'ქათმის ბურგერი',
      description: 'სრულყოფილება პურებს შორის.',
      price: '14.50₾',
      id: 8,
    },
  ];

  get filteredItems(): MenuItem[] {
    if (this.activeTab === 'ყველა') return this.menuItems;
    return this.menuItems.filter(item => item.tabs.includes(this.activeTab));
  }

  setActiveTab(tab: string): void {
    this.activeTab = tab;
  }

  trackById(_: number, item: MenuItem): number {
    return item.id;
  }
}
